WITH scored AS (SELECT *, AVG(amount) OVER (PARTITION BY status, store_id) AS status_avg_amount, AVG(discount) OVER (PARTITION BY store_id ORDER BY shipping_fee, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS discount_avg_2_prior, LAG(discount, 1) OVER (PARTITION BY channel ORDER BY amount, id) AS prev_discount, CUME_DIST() OVER (PARTITION BY customer_id ORDER BY discount NULLS LAST) AS discount_cume_dist, CORR(amount, discount) OVER (PARTITION BY channel) AS corr_amount_discount FROM orders WHERE status IN ('CANCELLED', 'SHIPPED')) SELECT CASE WHEN discount_avg_2_prior >= 0 THEN 'HIGH' ELSE 'LOW' END AS discount_avg_2_prior_tier, APPROX_PERCENTILE(discount_avg_2_prior, 0.5) AS discount_avg_2_prior_p50, ROUND(SUM(discount_cume_dist) / NULLIF(COUNT(CASE WHEN channel = 'web' THEN 1 END), 0), 2) AS discount_cume_dist_per_web FROM scored GROUP BY CASE WHEN discount_avg_2_prior >= 0 THEN 'HIGH' ELSE 'LOW' END ORDER BY discount_cume_dist_per_web DESC NULLS LAST;
